-- Grade 6 lesson videos: map Math/ELA/Science/World History to oEmbed-verified
-- YouTube URLs (Khan Academy channel preferred). Clear broken/mismatched IDs.
-- Prosper LessonVideo cover unchanged. Student text must not mention Khan/CKLA.
-- Do NOT run db:setup.

-- 1) Clear archived stub videos (prefer null)
UPDATE "Lesson" SET "videoUrl" = NULL WHERE "title" LIKE '[Archived stub]%' AND "courseId" IN (SELECT id FROM "Course" WHERE grade = 6);

